 function heading(){const s=selected();$('selectedTitle').textContent=catalogue.species[state.species].name+' · '+s.id;$('selectedNote').textContent=`${s.lat.toFixed(5)}°N, ${s.lon.toFixed(5)}°E · ${s.group}`;$('dialogTitle').textContent=$('selectedTitle').textContent;$('dialogSubtitle').textContent=$('selectedNote').textContent;$('mapSpecies').textContent=catalogue.species[state.species].name;$('mapRecord').textContent=`${stations().length.toLocaleString('en')} ${T('Model stations')} · ${scenarioName(state.scenario)} · ${state.year}`;$('recordNote').textContent=T(state.species==='longissima'?'Longissima model summary':'Japonica model summary');$('stationProvenance').textContent=T(state.species==='longissima'?'Longissima scope note':'Japonica nutrient note');$('mapNote').textContent=T(state.species==='longissima'?'Longissima scope note':'Japonica scope note');}
