 function mark(){if(selectedMarker)selectedMarker.remove();const s=selected();selectedMarker=L.circleMarker([s.lat,s.lon],{radius:8,color:'#284f5a',weight:2.3,fillColor:'#f7f5df',fillOpacity:.3,interactive:false}).addTo(map);}
