 $('species').onchange=async()=>{stop();state.species=$('species').value;state.scenario='historical';state.station=null;state.year=2020;state.from=state.species==='longissima'?1996:1991;state.to=state.species==='longissima'?2100:2020;state.period='historical';$('fromYear').value=state.from;$('toYear').value=state.to;stationData={};options();map.fitBounds(bounds());await Promise.all([maps(),loadStation()]);};
