 $('playYear').onclick=()=>{if(state.timer){stop();return;}$('playYear').textContent=T('Pause years');state.timer=setInterval(()=>{const last=+$('mapYear').max;state.year=state.year>=last?+$('mapYear').min:state.year+1;$('mapYear').value=state.year;maps().catch(e=>{stop();note(e.message);});},700);};
 for(const id of ['fromYear','toYear'])$(id).onchange=()=>{state.from=Math.max(1991,+$('fromYear').value);state.to=Math.min(2100,+$('toYear').value);if(state.from>state.to){state.to=state.from;$('toYear').value=state.to;}render();};$('resolution').onchange=()=>{state.resolution=$('resolution').value;render();};$('futureCurves').onchange=()=>{state.future=$('futureCurves').value;render();};$('budgetRecord').onchange=()=>{state.budgetRecord=$('budgetRecord').value;budget();};$('seasonPeriod').onchange=()=>{state.period=$('seasonPeriod').value;season();};$('downloadStation').onclick=download;$('printStation').onclick=()=>window.print();
