 const chartResize=new ResizeObserver(entries=>{for(const {target} of entries)if(target.clientWidth>0&&target.data)Plotly.relayout(target,{width:target.clientWidth,autosize:true});});for(const node of document.querySelectorAll('.plot'))chartResize.observe(node);
